/* Command action buttons (Manual mode) */
.msg-actions {
    display: flex;
    gap: 8px;
    margin-top: 10px;
}
.msg-action-btn {
    padding: 6px 14px;
    border-radius: 8px;
    border: none;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    display: flex; align-items: center; gap: 6px;
}
.msg-action-btn.send { background: var(--accent); color: #000; }
.msg-action-btn.send:hover { filter: brightness(1.1); }
.msg-action-btn.edit { background: transparent; border: 1px solid var(--border); color: var(--text-secondary); }
.msg-action-btn.edit:hover { border-color: var(--accent); color: var(--accent); }
.msg-action-btn.analyze { background: var(--blue); color: #fff; }
.msg-action-btn.skip { background: transparent; border: 1px solid var(--border); color: var(--text-secondary); }

/* Status bar */
.status-bar {
    display: none;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 20px;
    font-size: 0.82rem;
    align-self: flex-start;
}
.status-bar.active { display: flex; }
.status-btn {
    width: 34px; height: 34px;
    border-radius: 50%;
    border: 2px solid var(--border);
    background: transparent;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.85rem;
    transition: all 0.2s;
    flex-shrink: 0;
}
.status-btn.thinking { border-color: #fbbf24; color: #fbbf24; }
.status-btn.executing { border-color: #3b82f6; color: #3b82f6; }
.status-btn.done { border-color: #22c55e; color: #22c55e; pointer-events: none; }
.status-btn.stopped { border-color: #ef4444; color: #ef4444; pointer-events: none; }
.status-btn.error { border-color: #ef4444; color: #ef4444; pointer-events: none; }
.status-btn:hover:not(.done):not(.stopped):not(.error) {
    border-color: #ef4444; color: #ef4444; background: rgba(239,68,68,0.1);
}
@keyframes sb-pulse { 0%,100% { opacity:1; } 50% { opacity:0.4; } }
