.status-btn.executing i { animation: sb-spin 1.2s linear infinite; }
.status-divider { width: 1px; height: 18px; background: var(--border); flex-shrink: 0; }
.status-timer { opacity: 0.6; font-size: 0.75rem; white-space: nowrap; }
.status-action { color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 220px; }

/* Confirm buttons */
.confirm-buttons { display: flex; gap: 8px; margin-top: 8px; }
.btn-confirm {
    padding: 6px 14px; border-radius: 8px; border: none; cursor: pointer;
    font-size: 0.8rem; font-weight: 600; transition: all 0.2s;
}
.btn-confirm.yes { background: #22c55e; color: #fff; }
.btn-confirm.yes:hover { filter: brightness(1.1); }
.btn-confirm.clarify { background: transparent; border: 1px solid var(--blue); color: var(--blue); }
.btn-confirm.clarify:hover { background: rgba(59,130,246,0.1); }

