.input-area {
    flex-shrink: 0;
    padding: 12px 0 16px;
    border-top: 1px solid var(--border);
}
.input-wrapper {
    display: flex;
    gap: 10px;
    align-items: flex-end;
}
.input-field {
    flex: 1;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 12px 16px;
    color: var(--text-primary);
    font-size: 0.9rem;
    resize: none;
    outline: none;
    min-height: 44px;
    max-height: 150px;
    font-family: inherit;
    line-height: 1.4;
}

